def choose_move(observation):
    x, y = observation['self_position']
    width, height = observation['grid_width'], observation['grid_height']
    resources = observation['resources']
    obstacles = set(observation['obstacles'])
    op_x, op_y = observation['opponent_position']
    remaining = observation['remaining_resource_count']

    def valid(nx, ny):
        return 0 <= nx < width and 0 <= ny < height and (nx, ny) not in obstacles

    def dist(ax, ay, bx, by):
        return abs(ax - bx) + abs(ay - by)

    target = None
    min_d = float('inf')
    for rx, ry in resources:
        d = dist(x, y, rx, ry)
        if d < min_d:
            min_d = d
            target = (rx, ry)

    moves = [(0,1), (0,-1), (-1,0), (1,0), (0,0)]
    def score_mv(dx, dy):
        nx, ny = x + dx, y + dy
        if not valid(nx, ny):
            return -1
        s = -dist(nx, ny, *target) if target else 0
        if (nx, ny) == (op_x, op_y):
            s -= 5
        return s

    best = max(moves, key=lambda m: score_mv(*m))
    return list(best)
